"use client";

import React, { useState } from "react";
import Link from "next/link";
import { UserPlus } from "lucide-react";
import { LoginForm } from "./LoginForm";
import { OtpVerificationCard } from "../otp/OtpVerificationCard";

export const LoginCard: React.FC = () => {
  const [unverifiedData, setUnverifiedData] = useState<{
    email: string;
    otp: string;
  } | null>(null);

  if (unverifiedData) {
    return (
      <div className="w-full">
        <OtpVerificationCard
          email={unverifiedData.email}
          initialOtp={unverifiedData.otp}
          onSuccessRedirect={`/login?registered=true&email=${encodeURIComponent(
            unverifiedData.email
          )}`}
          onBackToLogin={() => setUnverifiedData(null)}
          title="Verify Your Email"
          subtitle="Your account email requires verification before you can log in."
          sourceText="Email Verification OTP"
        />
      </div>
    );
  }

  return (
    <div className="w-full">
      {/* Header */}
      <div className="text-center mb-7">
        <h1 className="text-2xl sm:text-3xl font-black text-neutral-900 uppercase tracking-tight">
          Welcome Back, <span className="text-[#71AC16]">Warrior</span>
        </h1>
        <p className="text-neutral-500 text-xs sm:text-sm mt-1.5 leading-relaxed">
          Log in to your Kratos Fitness account to continue your training
        </p>
      </div>

      {/* The Form */}
      <LoginForm
        onUnverifiedEmail={(data) => {
          setUnverifiedData(data);
        }}
      />

      {/* Registration Redirection Callout */}
      <div className="mt-8 pt-5 border-t border-neutral-200 text-center">
        <p className="text-xs text-neutral-600 flex items-center justify-center gap-2">
          <span>Don&apos;t have an account yet?</span>
          <Link
            href="/register"
            className="text-[#71AC16] hover:text-[#5d8d12] font-bold inline-flex items-center gap-1 hover:underline transition-colors"
          >
            <UserPlus className="w-3.5 h-3.5" />
            <span>Register here</span>
          </Link>
        </p>
      </div>
    </div>
  );
};
